python3 << 'EOF'
import os

for filename in os.listdir('/app/resources'):
    if filename.endswith('.txt') and not filename.startswith('._'):
        filepath = f'/app/resources/{filename}'
        try:
            with open(filepath, 'r', encoding='utf-8', errors='ignore') as f:
                content = f.read()
                if '2025' in content:
                    lines = content.split('\n')
                    for i, line in enumerate(lines):
                        if '2025' in line and ('surplus' in line.lower() or 'deficit' in line.lower() or 'budget' in line.lower() or 'est' in line.lower()):
                            print(f"\n=== {filename} line {i} ===")
                            print(line[:300])
        except Exception as e:
            print(f"Error with {filename}: {e}")
EOF
